using System;using System.Data;using System.Data.SqlClient;using System.Web;namespace schoolms{public partial class Profile:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){string email=Session["teacher"] as string;if(email==null){Response.Redirect("Teacher_login.aspx");return;}if(!IsPostBack)Load(email);}void Load(string e){try{using(SqlConnection c=Db.CreateConnection())using(SqlCommand q=new SqlCommand("SELECT Name,Email,Age,City,Department FROM Teacher WHERE Email=@E",c)){q.Parameters.Add("@E",SqlDbType.NVarChar,150).Value=e;c.Open();using(SqlDataReader r=q.ExecuteReader()){if(r.Read()){litTeacher.Text=HttpUtility.HtmlEncode(r.GetString(0))+" · "+HttpUtility.HtmlEncode(r.GetString(1));litProfile.Text="<div class='item'><b>Name:</b> "+HttpUtility.HtmlEncode(r.GetString(0))+"</div><div class='item'><b>Email:</b> "+HttpUtility.HtmlEncode(r.GetString(1))+"</div><div class='item'><b>Age:</b> "+r.GetInt32(2)+"</div><div class='item'><b>City:</b> "+(r.IsDBNull(3)?"-":HttpUtility.HtmlEncode(r.GetString(3)))+"</div><div class='item'><b>Department:</b> "+(r.IsDBNull(4)?"-":HttpUtility.HtmlEncode(r.GetString(4)))+"</div>";}}}}catch(SqlException){litProfile.Text="Unable to load profile.";}}}}
